package com.crisuhal.rebusques;

import android.app.*;import android.os.*;import android.content.*;import android.database.*;import android.database.sqlite.*;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.net.Uri;import android.view.*;import android.view.inputmethod.InputMethodManager;import android.widget.*;import java.io.*;import java.text.*;import java.util.*;

public class MainActivity extends Activity {
  final int BG=Color.rgb(246,244,237), GREEN=Color.rgb(18,60,54), TEAL=Color.rgb(25,123,104), GOLD=Color.rgb(242,181,68), INK=Color.rgb(36,48,45), MUTED=Color.rgb(110,120,114), WHITE=Color.WHITE;
  DB db; LinearLayout root,body,nav; TextView[] navItems=new TextView[4]; int page=0; String moneyPrefix="$ ";
  @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(GREEN);getWindow().setNavigationBarColor(GREEN);db=new DB(this);buildShell();showPage(0);}
  int d(float x){return (int)(x*getResources().getDisplayMetrics().density+.5f);} 
  GradientDrawable shape(int color,int radius){GradientDrawable g=new GradientDrawable();g.setColor(color);g.setCornerRadius(d(radius));return g;}
  TextView label(String s,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextColor(color);t.setTextSize(size);if(bold)t.setTypeface(null,Typeface.BOLD);return t;}
  LinearLayout vertical(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;}
  LinearLayout horizontal(){LinearLayout l=new LinearLayout(this);l.setOrientation(0);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
  void buildShell(){root=vertical();root.setBackgroundColor(BG);setContentView(root);LinearLayout head=horizontal();head.setPadding(d(18),d(9),d(18),d(8));head.setBackgroundColor(GREEN);LinearLayout logo=vertical();logo.setGravity(Gravity.CENTER);logo.setBackground(shape(GOLD,14));TextView mark=label("✦",22,GREEN,true);logo.addView(mark);head.addView(logo,new LinearLayout.LayoutParams(d(48),d(48)));LinearLayout titles=vertical();titles.setPadding(d(11),0,0,0);titles.addView(label("TALLER DE",10,0xffc3ded4,true));titles.addView(label("REBUSQUES",20,WHITE,true));head.addView(titles,new LinearLayout.LayoutParams(0,-2,1));TextView offline=label("● OFFLINE",10,0xffc3ded4,true);head.addView(offline);root.addView(head);ScrollView sc=new ScrollView(this);body=vertical();body.setPadding(d(16),d(14),d(16),d(22));sc.addView(body);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));nav=horizontal();nav.setPadding(d(5),d(5),d(5),d(5));nav.setBackgroundColor(WHITE);String[] names={"Inicio","Artículos","Ventas","Resumen"};String[] icons={"⌂","▦","＋","◔"};for(int i=0;i<4;i++){final int p=i;TextView t=label(icons[i]+"\n"+names[i],11,MUTED,true);t.setGravity(Gravity.CENTER);t.setPadding(0,d(4),0,d(4));t.setOnClickListener(v->showPage(p));navItems[i]=t;nav.addView(t,new LinearLayout.LayoutParams(0,d(55),1));}root.addView(nav);}
  void showPage(int p){page=p;for(int i=0;i<4;i++)navItems[i].setTextColor(i==p?TEAL:MUTED);body.removeAllViews();if(p==0)home();else if(p==1)productsPage();else if(p==2)salesPage();else reportPage();}
  void pad(View v,int top,int bottom){LinearLayout.LayoutParams q=new LinearLayout.LayoutParams(-1,-2);q.setMargins(0,d(top),0,d(bottom));body.addView(v,q);}
  TextView btn(String s,int color,int fg,Runnable run){TextView b=label(s,14,fg,true);b.setGravity(Gravity.CENTER);b.setPadding(d(14),d(13),d(14),d(13));b.setBackground(shape(color,14));b.setOnClickListener(v->run.run());return b;}
  void section(String s){TextView t=label(s,17,INK,true);pad(t,15,8);}
  LinearLayout card(){LinearLayout c=vertical();c.setPadding(d(16),d(15),d(16),d(15));c.setBackground(shape(WHITE,18));return c;}
  void home(){TextView hi=label("Tu rebusque, más ordenado.",23,GREEN,true);pad(hi,1,3);TextView sub=label("Anotá lo que entra, lo que sale y lo que te queda.",13,MUTED,false);pad(sub,0,15);
   LinearLayout metrics=horizontal();metrics.addView(metric("Ventas de hoy",fmt(db.todaySales()),"💸"),new LinearLayout.LayoutParams(0,-2,1));View gap=new View(this);metrics.addView(gap,new LinearLayout.LayoutParams(d(9),1));metrics.addView(metric("Ganancia estimada",fmt(db.profit()),"🌱"),new LinearLayout.LayoutParams(0,-2,1));pad(metrics,0,10);
   LinearLayout stock=card();stock.addView(label("📦  Artículos en stock",13,MUTED,true));stock.addView(label(db.stockCount()+" unidades · "+db.productCount()+" artículos",21,GREEN,true));pad(stock,0,6);
   LinearLayout actions=horizontal();actions.addView(btn("＋  Cargar venta",TEAL,WHITE,()->saleDialog()),new LinearLayout.LayoutParams(0,-2,1));View space=new View(this);actions.addView(space,new LinearLayout.LayoutParams(d(9),1));actions.addView(btn("＋  Artículo",GOLD,GREEN,()->productDialog(null)),new LinearLayout.LayoutParams(0,-2,1));pad(actions,10,0);
   section("Actividad reciente");ArrayList<String[]> recent=db.recent();if(recent.isEmpty()){empty("Todavía no hay movimientos.","Cargá una venta o un gasto y aparecen acá.");}else for(String[] row:recent){LinearLayout c=card();LinearLayout r=horizontal();TextView desc=label(row[0]+"\n"+row[1],14,INK,true);r.addView(desc,new LinearLayout.LayoutParams(0,-2,1));r.addView(label(row[2],14,TEAL,true));c.addView(r);pad(c,0,7);}}
  View metric(String title,String value,String icon){LinearLayout c=card();TextView i=label(icon,18,TEAL,true);c.addView(i);TextView v=label(value,20,GREEN,true);c.addView(v);TextView t=label(title,11,MUTED,false);c.addView(t);return c;}
  void empty(String title,String sub){LinearLayout c=card();c.addView(label(title,15,INK,true));TextView t=label(sub,13,MUTED,false);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=d(5);c.addView(t,p);pad(c,0,5);}
  void productsPage(){LinearLayout top=horizontal();top.addView(label("Tus artículos",22,GREEN,true),new LinearLayout.LayoutParams(0,-2,1));top.addView(btn("＋ Agregar",TEAL,WHITE,()->productDialog(null)));pad(top,0,12);TextView hint=label("Tocá para editar · mantené apretado para borrar",12,MUTED,false);pad(hint,0,8);ArrayList<Product> all=db.products();if(all.isEmpty())empty("Todavía no cargaste artículos.","Agregá productos o cosas usadas para empezar a controlar costos y stock.");for(Product p:all){LinearLayout c=card();LinearLayout row=horizontal();LinearLayout info=vertical();info.addView(label(p.name,16,INK,true));info.addView(label("Costo "+fmt(p.cost)+"  ·  Venta "+fmt(p.price),12,MUTED,false));row.addView(info,new LinearLayout.LayoutParams(0,-2,1));LinearLayout stock=vertical();stock.setGravity(Gravity.RIGHT);stock.addView(label("Stock",11,MUTED,false));stock.addView(label(""+p.stock,19,p.stock<=2?0xffb24c36:TEAL,true));row.addView(stock);c.addView(row);c.setOnClickListener(v->productDialog(p));c.setOnLongClickListener(v->{new AlertDialog.Builder(this).setTitle(p.name).setMessage("¿Querés quitar este artículo?").setNegativeButton("Cancelar",null).setPositiveButton("Borrar",(a,b)->{db.deleteProduct(p.id);showPage(1);}).show();return true;});pad(c,0,8);}}
  void salesPage(){TextView title=label("Movimientos",22,GREEN,true);pad(title,0,4);TextView intro=label("Registrá ventas y gastos para saber cómo viene el rebusque.",13,MUTED,false);pad(intro,0,14);LinearLayout actions=horizontal();actions.addView(btn("＋  Venta",TEAL,WHITE,()->saleDialog()),new LinearLayout.LayoutParams(0,-2,1));View gap=new View(this);actions.addView(gap,new LinearLayout.LayoutParams(d(8),1));actions.addView(btn("＋  Gasto",GOLD,GREEN,()->expenseDialog()),new LinearLayout.LayoutParams(0,-2,1));pad(actions,0,14);ArrayList<String[]> all=db.allMoves();if(all.isEmpty())empty("Sin movimientos todavía.","Las ventas descuentan el stock y quedan anotadas con fecha.");for(String[] a:all){LinearLayout c=card();LinearLayout r=horizontal();r.addView(label(a[0]+"\n"+a[1],14,INK,true),new LinearLayout.LayoutParams(0,-2,1));r.addView(label(a[2],14,a[3].equals("gasto")?0xffb24c36:TEAL,true));c.addView(r);pad(c,0,7);}}
  void reportPage(){TextView title=label("Resumen del negocio",22,GREEN,true);pad(title,0,4);pad(label("Una cuenta simple para mirar el mes.",13,MUTED,false),0,12);LinearLayout c=card();line(c,"Ventas totales",fmt(db.totalSales()));line(c,"Costo de lo vendido",fmt(db.costSold()));line(c,"Ganancia antes de gastos",fmt(db.totalSales()-db.costSold()));line(c,"Gastos registrados",fmt(db.totalExpenses()));View div=new View(this);div.setBackgroundColor(0xffe3e7e1);LinearLayout.LayoutParams dp=new LinearLayout.LayoutParams(-1,d(1));dp.setMargins(0,d(8),0,d(8));c.addView(div,dp);line(c,"Resultado estimado",fmt(db.profit()));pad(c,0,12);LinearLayout cat=card();cat.addView(label("Importante",15,GREEN,true));TextView note=label("Esto es una cuenta orientativa con los costos y movimientos que cargaste. No incluye impuestos, comisiones ni otros costos que no hayas anotado.",13,MUTED,false);note.setPadding(0,d(6),0,0);cat.addView(note);pad(cat,0,10);pad(btn("Exportar CSV",GREEN,WHITE,()->exportCsv()),0,8);pad(btn("Borrar todos los datos",0xfff3e7e2,0xffa13f2f,()->confirmClear()),0,8);}
  void line(LinearLayout c,String k,String v){LinearLayout r=horizontal();r.setPadding(0,d(6),0,d(6));r.addView(label(k,14,MUTED,false),new LinearLayout.LayoutParams(0,-2,1));r.addView(label(v,15,INK,true));c.addView(r);}
  String fmt(double x){return "$"+new DecimalFormat("#,##0.00",new DecimalFormatSymbols(new Locale("es","AR"))).format(x);}
  EditText edit(String hint,int type){EditText e=new EditText(this);e.setSingleLine(true);e.setHint(hint);e.setInputType(type);e.setTextSize(16);return e;}
  double val(EditText e){try{return Double.parseDouble(e.getText().toString().trim().replace(',','.'));}catch(Exception x){return -1;}}
  void productDialog(Product old){LinearLayout form=vertical();EditText name=edit("Nombre del artículo",android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);EditText cost=edit("Costo por unidad",android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);EditText price=edit("Precio de venta por unidad",android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);EditText stock=edit("Unidades en stock",android.text.InputType.TYPE_CLASS_NUMBER);form.addView(name);form.addView(cost);form.addView(price);form.addView(stock);if(old!=null){name.setText(old.name);cost.setText(""+old.cost);price.setText(""+old.price);stock.setText(""+old.stock);}AlertDialog dialog=new AlertDialog.Builder(this).setTitle(old==null?"Agregar artículo":"Editar artículo").setView(form).setNegativeButton("Cancelar",null).setPositiveButton("Guardar",null).create();dialog.setOnShowListener(x->dialog.getButton(-1).setOnClickListener(v->{String n=name.getText().toString().trim();double co=val(cost),pr=val(price);int st;try{st=Integer.parseInt(stock.getText().toString().trim());}catch(Exception ex){st=-1;}if(n.isEmpty()||co<0||pr<0||st<0){toast("Completá nombre, costo, precio y stock con valores válidos.");return;}if(old==null)db.addProduct(n,co,pr,st);else db.updateProduct(old.id,n,co,pr,st);dialog.dismiss();showPage(1);}));dialog.show();}
  void saleDialog(){ArrayList<Product> items=db.products();if(items.isEmpty()){new AlertDialog.Builder(this).setMessage("Primero agregá un artículo para registrar una venta.").setPositiveButton("Agregar artículo",(a,b)->productDialog(null)).setNegativeButton("Cerrar",null).show();return;}LinearLayout form=vertical();Spinner sp=new Spinner(this);ArrayList<String> names=new ArrayList<>();for(Product p:items)names.add(p.name+" · stock "+p.stock+" · "+fmt(p.price));sp.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,names));EditText qty=edit("Cantidad vendida",android.text.InputType.TYPE_CLASS_NUMBER);form.addView(label("Artículo",13,MUTED,true));form.addView(sp);form.addView(qty);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Registrar venta").setView(form).setNegativeButton("Cancelar",null).setPositiveButton("Guardar",null).create();dialog.setOnShowListener(x->dialog.getButton(-1).setOnClickListener(v->{int q;try{q=Integer.parseInt(qty.getText().toString());}catch(Exception ex){q=0;}Product selected=items.get(sp.getSelectedItemPosition());if(q<=0){toast("Poné una cantidad válida.");return;}if(q>selected.stock){toast("No alcanza el stock: hay "+selected.stock+" unidades.");return;}db.sale(selected,q);dialog.dismiss();showPage(page);}));dialog.show();}
  void expenseDialog(){LinearLayout f=vertical();EditText name=edit("En qué gastaste",android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);EditText amount=edit("Importe",android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);f.addView(name);f.addView(amount);AlertDialog dlg=new AlertDialog.Builder(this).setTitle("Anotar gasto").setView(f).setNegativeButton("Cancelar",null).setPositiveButton("Guardar",null).create();dlg.setOnShowListener(v->dlg.getButton(-1).setOnClickListener(b->{double a=val(amount);String n=name.getText().toString().trim();if(n.isEmpty()||a<=0){toast("Completá el motivo y un importe válido.");return;}db.expense(n,a);dlg.dismiss();showPage(page);}));dlg.show();}
  void confirmClear(){new AlertDialog.Builder(this).setTitle("¿Borrar todos los datos?").setMessage("Se eliminarán artículos, ventas y gastos guardados en este teléfono. No se puede deshacer.").setNegativeButton("Cancelar",null).setPositiveButton("Borrar",(d,w)->{db.clear();showPage(0);}).show();}
  void exportCsv(){Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("text/csv");i.putExtra(Intent.EXTRA_TITLE,"taller_de_rebusques.csv");startActivityForResult(i,22);}
  @Override protected void onActivityResult(int req,int res,Intent data){super.onActivityResult(req,res,data);if(req==22&&res==RESULT_OK&&data!=null){try(OutputStream out=getContentResolver().openOutputStream(data.getData())){out.write(db.csv().getBytes("UTF-8"));toast("CSV exportado.");}catch(Exception e){toast("No pude guardar el CSV.");}}}
  void toast(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();}
  class Product{long id;String name;double cost,price;int stock;Product(long i,String n,double c,double p,int s){id=i;name=n;cost=c;price=p;stock=s;}}
  class DB extends SQLiteOpenHelper{
    DB(Context c){super(c,"rebusques.db",null,1);}public void onCreate(SQLiteDatabase d){d.execSQL("CREATE TABLE products(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,cost REAL NOT NULL,price REAL NOT NULL,stock INTEGER NOT NULL)");d.execSQL("CREATE TABLE moves(id INTEGER PRIMARY KEY AUTOINCREMENT,type TEXT NOT NULL,description TEXT NOT NULL,amount REAL NOT NULL,cost REAL NOT NULL DEFAULT 0,qty INTEGER NOT NULL DEFAULT 0,product_id INTEGER,date TEXT NOT NULL)");}public void onUpgrade(SQLiteDatabase d,int a,int b){}
    void addProduct(String n,double c,double p,int s){ContentValues v=new ContentValues();v.put("name",n);v.put("cost",c);v.put("price",p);v.put("stock",s);getWritableDatabase().insert("products",null,v);}
    void updateProduct(long id,String n,double c,double p,int s){ContentValues v=new ContentValues();v.put("name",n);v.put("cost",c);v.put("price",p);v.put("stock",s);getWritableDatabase().update("products",v,"id=?",new String[]{""+id});}
    void deleteProduct(long id){getWritableDatabase().delete("products","id=?",new String[]{""+id});}
    ArrayList<Product> products(){ArrayList<Product> a=new ArrayList<>();try(Cursor c=getReadableDatabase().rawQuery("SELECT id,name,cost,price,stock FROM products ORDER BY name COLLATE NOCASE",null)){while(c.moveToNext())a.add(new Product(c.getLong(0),c.getString(1),c.getDouble(2),c.getDouble(3),c.getInt(4)));}return a;}
    Product find(long id){try(Cursor c=getReadableDatabase().rawQuery("SELECT id,name,cost,price,stock FROM products WHERE id=?",new String[]{""+id})){if(c.moveToFirst())return new Product(c.getLong(0),c.getString(1),c.getDouble(2),c.getDouble(3),c.getInt(4));}return null;}
    void sale(Product p,int q){SQLiteDatabase d=getWritableDatabase();d.beginTransaction();try{ContentValues cv=new ContentValues();cv.put("stock",p.stock-q);d.update("products",cv,"id=? AND stock>=?",new String[]{""+p.id,""+q});ContentValues m=new ContentValues();m.put("type","venta");m.put("description",p.name+" × "+q);m.put("amount",p.price*q);m.put("cost",p.cost*q);m.put("qty",q);m.put("product_id",p.id);m.put("date",now());d.insert("moves",null,m);d.setTransactionSuccessful();}finally{d.endTransaction();}}
    void expense(String n,double a){ContentValues m=new ContentValues();m.put("type","gasto");m.put("description",n);m.put("amount",a);m.put("cost",0);m.put("qty",0);m.put("date",now());getWritableDatabase().insert("moves",null,m);}
    String now(){return new SimpleDateFormat("yyyy-MM-dd HH:mm",Locale.getDefault()).format(new Date());}
    double sum(String sql){try(Cursor c=getReadableDatabase().rawQuery(sql,null)){if(c.moveToFirst())return c.getDouble(0);}return 0;}
    double totalSales(){return sum("SELECT COALESCE(SUM(amount),0) FROM moves WHERE type='venta'");}double totalExpenses(){return sum("SELECT COALESCE(SUM(amount),0) FROM moves WHERE type='gasto'");}double costSold(){return sum("SELECT COALESCE(SUM(cost),0) FROM moves WHERE type='venta'");}double profit(){return totalSales()-costSold()-totalExpenses();}
    double todaySales(){String day=new SimpleDateFormat("yyyy-MM-dd",Locale.getDefault()).format(new Date());try(Cursor c=getReadableDatabase().rawQuery("SELECT COALESCE(SUM(amount),0) FROM moves WHERE type='venta' AND date LIKE ?",new String[]{day+"%"})){return c.moveToFirst()?c.getDouble(0):0;}}
    int stockCount(){return (int)sum("SELECT COALESCE(SUM(stock),0) FROM products");}int productCount(){return (int)sum("SELECT COUNT(*) FROM products");}
    ArrayList<String[]> recent(){return queryMoves("SELECT type,description,amount,date FROM moves ORDER BY id DESC LIMIT 5");}ArrayList<String[]> allMoves(){return queryMoves("SELECT type,description,amount,date FROM moves ORDER BY id DESC");}
    ArrayList<String[]> queryMoves(String sql){ArrayList<String[]> a=new ArrayList<>();try(Cursor c=getReadableDatabase().rawQuery(sql,null)){while(c.moveToNext()){String type=c.getString(0);a.add(new String[]{(type.equals("venta")?"🟢 ":"🟠 ")+c.getString(1),c.getString(3),(type.equals("venta")?"+":"−")+fmt(c.getDouble(2)),type});}}return a;}
    String csv(){StringBuilder s=new StringBuilder("TIPO,DESCRIPCION,IMPORTE,COSTO,CANTIDAD,FECHA\n");try(Cursor c=getReadableDatabase().rawQuery("SELECT type,description,amount,cost,qty,date FROM moves ORDER BY id",null)){while(c.moveToNext())s.append(csvq(c.getString(0))).append(',').append(csvq(c.getString(1))).append(',').append(c.getDouble(2)).append(',').append(c.getDouble(3)).append(',').append(c.getInt(4)).append(',').append(csvq(c.getString(5))).append('\n');}s.append("\nARTICULOS, NOMBRE, COSTO, PRECIO, STOCK\n");try(Cursor c=getReadableDatabase().rawQuery("SELECT name,cost,price,stock FROM products ORDER BY name",null)){while(c.moveToNext())s.append("articulo,").append(csvq(c.getString(0))).append(',').append(c.getDouble(1)).append(',').append(c.getDouble(2)).append(',').append(c.getInt(3)).append('\n');}return s.toString();}
    String csvq(String x){return "\""+x.replace("\"","\"\"")+"\"";}void clear(){getWritableDatabase().delete("moves",null,null);getWritableDatabase().delete("products",null,null);}
  }
}
